51	  if (!c.expected) return claims.length === 0 ? "CLEAR" : "FP";
52	  if (!c.expected.checks.includes(check)) return claims.length === 0 ? "CLEAR" : "EXTRA";
53	  return claims.some((claim) => matchesClaim(c.expected!, claim, check)) ? "HIT" : "MISS";
54	}
