56	/** No provider error bodies or model prose can reach stdout or the report. */
57	export function safeError(error: unknown): string {
58	  if (error instanceof Error && /Gemini returned \d{3}/.test(error.message)) {
59	    return /Gemini returned \d{3}/.exec(error.message)![0];
60	  }
61	  if (error instanceof Error && error.name === "ZodError") return "schema-validation";
62	  if (error instanceof SyntaxError) return "invalid-json";
63	  return "provider-or-harness-error";
64	}
