66	export async function runMatrix(
67	  cases: EvalCase[], checks: CheckDefinition[], llm: LlmProvider, model: string,
68	  onRow?: (row: Row) => void,
69	): Promise<Matrix> {
70	  for (const name of checkNames) {
71	    if (!checks.some((check) => check.name === name)) throw new Error(`Missing check: ${name}`);
72	  }
73	  const result: Matrix = {
74	    provider: llm.id, model, date: new Date().toISOString(),
75	    checkHashes: Object.fromEntries(checks.map((c) => [c.name, hash(c.prompt)])), rows: [], stopped: false,
76	  };
77	  for (const c of cases) {
78	    const row: Row = {
79	      id: c.id, kind: c.expected ? "bug" : "clean", fixtureHash: hash(c),
80	      cells: [],
81	    };
82	    if (result.stopped) {
83	      row.cells = checkNames.map((check) => emptyCell(check, "NOT-RUN"));
84	    } else {
85	      const { repo, base, head } = fixtureRepo(c.before, c.after);
86	      try {
87	        const change = await loadChange(repo, base, head);
88	        const gate = runPrechecks(change, defaults) ?? scanForInjection(change.diff);
89	        if (gate) {
90	          row.gate = gate.reason;
91	          row.cells = checkNames.map((check) => emptyCell(check, "GATE"));
92	        } else {
93	          for (const name of checkNames) {
94	            if (result.stopped) {
95	              row.cells.push(emptyCell(name, "NOT-RUN"));
96	              continue;
97	            }
98	            const meter = new MeteredProvider(llm, defaults.maxInputTokens);
99	            const started = performance.now();
100	            try {
101	              // Exactly the production check, schema and untrusted wrappers. One at a time.
102	              const claims = await runChecks([checks.find((check) => check.name === name)!], change,
103	                { source: "request", intent: c.intent, transcript: null }, meter);
104	              row.cells.push({
105	                check: name, status: gradeClaims(c, name, claims), claims: claims.length,
106	                latencyMs: Math.round(performance.now() - started),
107	                inputTokens: meter.usage.inputTokens, outputTokens: meter.usage.outputTokens,
108	                outputHash: hash(claims),
109	              });
110	            } catch (error) {
111	              const category = safeError(error);
112	              row.cells.push({ ...emptyCell(name, "ERROR"), latencyMs: Math.round(performance.now() - started), error: category });
113	              if (category === "Gemini returned 429") result.stopped = true;
114	            }
115	          }
116	        }
117	      } finally {
118	        await rm(repo, { recursive: true, force: true });
119	      }
120	    }
121	    result.rows.push(row);
122	    onRow?.(row);
123	  }
124	  return result;
125	}
