127	function emptyCell(check: CheckName, status: Status): Cell {
128	  return { check, status, claims: 0, latencyMs: 0, inputTokens: 0, outputTokens: 0 };
129	}
130	
131	const completed = (cell: Cell) => !["GATE", "ERROR", "NOT-RUN"].includes(cell.status);
132	const rate = (n: number, d: number) => d ? `${n}/${d} (${(100 * n / d).toFixed(1)}%)` : "n/a (0 observations)";
133	
134	export function summarize(matrix: Matrix, cases: EvalCase[]) {
135	  const bugs = matrix.rows.filter((row) => row.kind === "bug");
136	  const clean = matrix.rows.filter((row) => row.kind === "clean" && !row.gate);
137	  const measuredClean = clean.filter((row) => row.cells.every(completed));
138	  const measuredBugs = bugs.filter((row) => row.cells.every(completed));
139	  const found = bugs.filter((row) => row.cells.some((cell) => cell.status === "HIT")).length;
140	  const fp = measuredClean.filter((row) => row.cells.some((cell) => cell.status === "FP")).length;
141	  const cells = matrix.rows.flatMap((row) => row.cells);
142	  return {
143	    recall: rate(found, cases.filter((c) => c.expected).length),
144	    observedRecall: rate(measuredBugs.filter((r) => r.cells.some((c) => c.status === "HIT")).length, measuredBugs.length),
145	    falsePositiveRate: rate(fp, measuredClean.length),
146	    complete: !matrix.stopped && cells.every((c) => c.status !== "ERROR" && c.status !== "NOT-RUN")
147	      && matrix.rows.every((r) => r.gate === cases.find((c) => c.id === r.id)?.gate),
148	    inputTokens: cells.reduce((n, c) => n + c.inputTokens, 0),
149	    outputTokens: cells.reduce((n, c) => n + c.outputTokens, 0),
150	    latencyMs: cells.reduce((n, c) => n + c.latencyMs, 0),
151	    calls: cells.filter((c) => completed(c) || c.status === "ERROR").length,
152	    perCheck: checkNames.map((check) => {
153	      const positives = matrix.rows.filter((r) => cases.find((c) => c.id === r.id)?.expected?.checks.includes(check));
154	      const observed = positives.filter((r) => r.cells.some((c) => c.check === check && completed(c)));
155	      return {
156	        check, recall: rate(positives.filter((r) => r.cells.some((c) => c.check === check && c.status === "HIT")).length, positives.length),
157	        observedRecall: rate(observed.filter((r) => r.cells.some((c) => c.check === check && c.status === "HIT")).length, observed.length),
158	        falsePositiveRate: rate(measuredClean.filter((r) => r.cells.some((c) => c.check === check && c.status === "FP")).length, measuredClean.length),
159	      };
160	    }),
161	  };
162	}
