164	export function formatRow(row: Row): string {
165	  const total = (key: "latencyMs" | "inputTokens" | "outputTokens") => row.cells.reduce((n, c) => n + c[key], 0);
166	  return `| ${row.id} | ${row.cells.map((c) => c.status).join(" | ")} | ${total("latencyMs")} | ${total("inputTokens")} / ${total("outputTokens")} |`;
167	}
