169	export function report(matrix: Matrix, cases: EvalCase[]): string {
170	  const s = summarize(matrix, cases);
171	  const failures = matrix.rows.flatMap((row) => row.cells
172	    .filter((c) => ["MISS", "FP", "EXTRA", "ERROR", "NOT-RUN"].includes(c.status))
173	    .map((c) => `- **${row.id} / ${c.check}: ${c.status}**; ${c.claims} claims.${c.error ? ` Error: ${c.error}.` : ""}`));
174	  for (const row of matrix.rows) {
175	    const wantedGate = cases.find((c) => c.id === row.id)?.gate;
176	    if (row.cells.some((c) => c.status !== "NOT-RUN") && row.gate !== wantedGate) {
177	      failures.push(`- **${row.id}: unexpected gate**; expected ${wantedGate ?? "none"}, got ${row.gate ?? "none"}.`);
178	    }
179	  }
180	  return `# Live check evals\n\n` +
181	    `## Recorded run\n\n` +
182	    `- Date (UTC): ${matrix.date}\n- Provider: ${matrix.provider}; configured model: ${matrix.model}\n` +
183	    `- Run complete: **${s.complete ? "yes" : "no — do not treat missing observations as model successes"}**\n` +
184	    `- Full-corpus detection lower bound (any check finds the expected claim; unmeasured cases remain in denominator): **${s.recall}**\n` +
185	    `- Recall on fully observed bug cases: **${s.observedRecall}**\n` +
186	    `- False-positive rate (any claim on fully observed clean code cases): **${s.falsePositiveRate}**\n` +
187	    `- Sequential check latency: **${s.latencyMs} ms** total; ${s.calls ? Math.round(s.latencyMs / s.calls) : 0} ms mean per attempted cell\n` +
188	    `- Check calls attempted: ${s.calls} (provider may retry transient non-429 failures); reported tokens: **${s.inputTokens} input / ${s.outputTokens} output**\n` +
189	    `- Failed requests have unknown token usage, not an observed zero. Output tokens are Gemini's candidatesTokenCount; internal thinking tokens are not included.\n\n` +
190	    `| Check | Full-corpus detection lower bound | Recall on observed target cells | Clean-code false-positive rate |\n| --- | --- | --- | --- |\n` +
191	    s.perCheck.map((c) => `| ${c.check} | ${c.recall} | ${c.observedRecall} | ${c.falsePositiveRate} |`).join("\n") +
192	    `\n\n## Check-by-case matrix\n\n| Case | behaviour-change | failure-path | silent-decision | Latency ms | Tokens in / out |\n| --- | --- | --- | --- | ---: | ---: |\n` +
193	    matrix.rows.map(formatRow).join("\n") +
194	    `\n\nHIT = anchored expected claim found; MISS = expected claim not matched (even if another claim exists); CLEAR = no claim expected or emitted; FP = clean code flagged; EXTRA = off-scope check emitted a claim on a bug case; GATE = deterministic bypass; ERROR / NOT-RUN = unmeasured. EXTRA is reported but excluded from the clean-case FP denominator.\n\n` +
195	    `## Every failure / unexpected finding\n\n${failures.join("\n") || "None."}\n\n` +
196	    `## Fixed case rubric\n\n` + cases.map((c) => `- **${c.id}**: ${c.expected ? `${c.expected.description} Anchor: \`${c.expected.file}:${c.expected.lines.join("-")}\`; target checks: ${c.expected.checks.join(", ")}. Required concept groups: ${c.expected.concepts.map(String).map((r) => `\`${r}\``).join(" AND ")}.` : c.gate ? "Docs-only; must bypass all model checks." : "Clean refactor; every check must return zero claims."}`).join("\n") +
197	    `\n\n## Method and reproduction\n\n` +
198	    "- `pnpm evals` stays offline: the original six pipeline smoke cases assert deterministic mock behaviour; this matrix also runs with MockProvider, whose scores are NOT model-quality evidence. Mock matrix scores do not gate CI.\n" +
199	    "- Run `pnpm evals:live --report docs/EVALS.md` to explicitly use Gemini. Loads root .env (existing environment wins); skips successfully without GEMINI_API_KEY. GEMINI_MODEL defaults to gemini-3.5-flash-lite. No fallback model is used, keeping attribution unambiguous.\n" +
200	    `- Each cell calls production runChecks with exactly one unchanged check markdown prompt and the production zod schema/untrusted wrappers. Checks and cases are sequential. The first 429 stops the entire run, without retrying the 429 or falling back. Deterministic prechecks and injection scan run first; docs bypass is excluded from model clean-case metrics.\n` +
201	    `- Fixtures are hand-written before/after files committed to temporary Git repositories; production loadChange generates the diff. Repositories are removed afterwards. No code from fixtures is installed or executed.\n` +
202	    `- The hand-authored expected claim/rubric is never sent to the model. One claim must overlap the fixed file/line anchor and match ALL concept regexes in its summary/evidence; silent-decision must also label it silent. No model grades another model.\n` +
203	    `- This lexical score is reproducible but can reject correct paraphrases and accept sufficiently similar incorrect prose. It measures seeded claim detection, not exam-question usefulness, correctness of all extra claims, or end-to-end planning/risk thresholds. One small, single-run corpus is not a general accuracy estimate. No check prompts were tuned for this run.\n` +
204	    `- Only score/count/timing metadata and hashes are retained. No raw model output, repository diffs, transcripts, API error bodies, or secrets are logged or stored in this report.\n\n` +
205	    `## Provenance (SHA-256)\n\n` +
206	    `Check prompt hashes:\n\n${Object.entries(matrix.checkHashes).map(([name, h]) => `- ${name}: ${h}`).join("\n")}\n\n` +
207	    `| Case | Fixture + rubric hash | Per-check output hashes (matrix order; — means no parsed output) |\n| --- | --- | --- |\n` +
208	    matrix.rows.map((r) => `| ${r.id} | ${r.fixtureHash} | ${r.cells.map((c) => c.outputHash ?? "—").join(" / ")} |`).join("\n") + "\n";
209	}
